type Fn<T> = () => Promise<T>;

function promiseAll<T>(functions: Fn<T>[]): Promise<T[]> {
    return new Promise<T[]>((resolve, reject) => {
        if (functions.length === 0) {
            resolve([]);
            return;
        }
        const results = new Array<T>(functions.length);
        let completed = 0;
        functions.forEach((fn, idx) => {
            fn().then(
                val => {
                    results[idx] = val;
                    completed++;
                    if (completed === functions.length) {
                        resolve(results);
                    }
                },
                err => reject(err)
            );
        });
    });
}
